        const __m512d t32 = _mm512_add_pd(t16, t31);
        const __m512d t43 = _mm512_sub_pd(t31, t16);
        const __m512d t39 = _mm512_add_pd(t24, t27);
        const __m512d t40 = _mm512_sub_pd(t39, t36);
        const __m512d t45 = _mm512_add_pd(t36, t39);
        const __m512d t28 = lane_im_0;
        const __m512d t29 = _mm512_sub_pd(t28, t25);
        const __m512d t34 = _mm512_sub_pd(t29, t18);
        const __m512d t44 = _mm512_add_pd(t18, t29);
