        _mm512_storeu_pd(&zout[2*(size_t)k + 8], _mm512_permutex2var_pd(_pr_0, _zs_po, _qi_0));
        const __m512d _pr_1 = t43;
        const __m512d _qi_1 = t44;
        _mm512_storeu_pd(&zout[2*((size_t)1*OLs + k)], _mm512_permutex2var_pd(_pr_1, _zs_pe, _qi_1));
        _mm512_storeu_pd(&zout[2*((size_t)1*OLs + k) + 8], _mm512_permutex2var_pd(_pr_1, _zs_po, _qi_1));
        const __m512d _pr_2 = t40;
        const __m512d _qi_2 = t42;
        _mm512_storeu_pd(&zout[2*((size_t)2*OLs + k)], _mm512_permutex2var_pd(_pr_2, _zs_pe, _qi_2));
        _mm512_storeu_pd(&zout[2*((size_t)2*OLs + k) + 8], _mm512_permutex2var_pd(_pr_2, _zs_po, _qi_2));
        const __m512d _pr_3 = t32;
        const __m512d _qi_3 = t34;
        _mm512_storeu_pd(&zout[2*((size_t)3*OLs + k)], _mm512_permutex2var_pd(_pr_3, _zs_pe, _qi_3));
